package membuntdb

import (
	"fmt"
	"math"
	"testing"

	"github.com/singchia/frontier/pkg/frontier/config"
	"github.com/singchia/frontier/pkg/frontier/repo/model"
	"github.com/singchia/frontier/pkg/frontier/repo/query"
)

func TestLargeIDsKeepIndependentRegistrations(t *testing.T) {
	// IDs generated by Geminio exceed the exact integer range of float64.
	const a = uint64(7690000000000000000)
	const b = a + 1
	dao, err := NewDao(&config.Configuration{})
	if err != nil {
		t.Fatal(err)
	}
	defer dao.Close()
	for _, id := range []uint64{a, b} {
		if err = dao.CreateServiceRPC(&model.ServiceRPC{ServiceID: id, RPC: "callback"}); err != nil {
			t.Fatal(err)
		}
		if err = dao.CreateServiceTopic(&model.ServiceTopic{ServiceID: id, Topic: "events"}); err != nil {
			t.Fatal(err)
		}
		if err = dao.CreateEdgeRPC(&model.EdgeRPC{EdgeID: id, RPC: "echo"}); err != nil {
			t.Fatal(err)
		}
	}
	if err = dao.DeleteServiceRPCs(a); err != nil {
		t.Fatal(err)
	}
	rpcs, err := dao.GetServiceRPCs("callback")
	if err != nil {
		t.Fatal(err)
	}
	if len(rpcs) != 1 || rpcs[0].ServiceID != b {
		t.Errorf("deleting Service %d removed another Service's RPC: %+v", a, rpcs)
	}
	if err = dao.DeleteServiceTopics(a); err != nil {
		t.Fatal(err)
	}
	topics, err := dao.GetServiceTopics("events")
	if err != nil {
		t.Fatal(err)
	}
	if len(topics) != 1 || topics[0].ServiceID != b {
		t.Errorf("deleting Service %d removed another Service's topic: %+v", a, topics)
	}
	if err = dao.DeleteEdgeRPCs(a); err != nil {
		t.Fatal(err)
	}
	edges, err := dao.ListEdgeRPCs(&query.EdgeRPCQuery{EdgeID: b})
	if err != nil {
		t.Fatal(err)
	}
	if len(edges) != 1 || edges[0] != "echo" {
		t.Errorf("deleting Edge %d removed another Edge's RPC: %+v", a, edges)
	}
}

func TestUint64IndexBoundaries(t *testing.T) {
	less := indexUint64("service_id")
	for _, id := range []uint64{0, 1, 1<<53 - 1, 1 << 53, 7690000000000000000, math.MaxUint64 - 1} {
		a := fmt.Sprintf(`{"service_id":%d}`, id)
		b := fmt.Sprintf(`{"service_id":%d}`, id+1)
		if !less(a, b) || less(b, a) || less(a, a) {
			t.Fatalf("integer index lost precision at %d", id)
		}
	}
}
